{
  "title": "serialization-error-detail",
  "request": "Hey, the SerializationError from SafeSerializer is pretty vague. Can you make it include the object's representation and a hint about allow_pickle=True?",
  "edits": [
    {
      "path": "src/smolagents/serialization.py",
      "search": "raise SerializationError(f"Cannot safely serialize object of type {type_name}")",
      "replace": "        raise SerializationError(
            f"Cannot safely serialize object of type {type_name!r} (value: {repr(obj)}). "
            "Consider setting allow_pickle=True if you trust the source."
        )"
    }
  ],
  "test_path": "tests/test_serialization_error_message.py",
  "test": "import pytest
from smolagents.serialization import SafeSerializer, SerializationError

class Dummy:
    def __init__(self):
        self.x = 1

def test_serialization_error_message():
    dummy = Dummy()
    with pytest.raises(SerializationError) as excinfo:
        SafeSerializer.dumps(dummy)
    msg = str(excinfo.value)
    assert "Consider setting allow_pickle" in msg
"
}
